const st = window.__ensemble;
for (let i = 0; i < 10; i++) {
  if (st.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
localStorage.removeItem('ensemble.voice.ready');
return 'onboarded: ' + st.getState().settings.onboarded

window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); await new Promise(r => setTimeout(r, 150)); localStorage.setItem('ensemble.voice.ready', '1');
const box = document.querySelector('textarea'); const before = box.value;
const real = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
navigator.mediaDevices.getUserMedia = () => Promise.reject(new DOMException('no', 'NotAllowedError'));
[...document.querySelectorAll('button')].find(b => /^Speak instead of typing/.test(b.getAttribute('aria-label') || '')).click(); await new Promise(r => setTimeout(r, 600));
navigator.mediaDevices.getUserMedia = real;
const t = window.__ensemble.getState().toasts; const last = t[t.length - 1];
return 'FAIL blocked: said ' + JSON.stringify(last && last.text) + ' | box unchanged: ' + (box.value === before)

